head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _2 : getDescendantRowIndexArray @param rowIndex 의 MultiLine caveat 전용 샘플.
//     한 데이터 레코드(Row 인덱스 N)를 2개의 Line(TR)으로 표시(MultiLine).
//       Line1 : name(drilldown 트리) | amount
//       Line2 : memo(일반 text 셀, colspan 병합)
//     · "Body 가 MultiLine 일때 각 Line 의 Row 인덱스값은 같습니다." caveat 를 입증 :
//       한 레코드가 화면상 Line1/Line2 두 TR 로 렌더돼도 rowIndex 는 하나(DataList 인덱스)뿐이므로
//       그 rowIndex 로 getDescendantRowIndexArray 를 호출하면 두 Line 모두 동일한 모든 자손 배열을 반환한다.
scwin.tData = {
    "description" : "[gridView > M > getDescendantRowIndexArray]<br/>DrillDown 이 적용되었을때 특정 Row 의 모든 자식 Row 인덱스값을 배열로 반환합니다.",
    "validation" : [
        "Body 가 MultiLine 일때 각 Line 의 Row 인덱스값은 같습니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 검증 데이터 — DrillDown(3단 트리) + MultiLine(레코드당 2 Line) 구성.
//  한 레코드는 화면상 2개의 Line(TR)으로 렌더됨.
//   Line1 : name(drilldown 트리 컬럼) | amount
//   Line2 : memo(일반 text, colspan 병합)
//  계층(DataList idx) : idx0 영업본부(depth1) > idx1 영업1팀(depth2) > idx2 김영업(depth3), idx3 개발본부(depth1)
scwin.GRID_DATA = [
    { "name": "영업본부", "amount": 100, "memo": "영업본부 memo Line", "depth": 1 },
    { "name": "영업1팀", "amount": 110, "memo": "영업1팀 memo Line",  "depth": 2 },
    { "name": "김영업",   "amount": 111, "memo": "김영업 memo Line",   "depth": 3 },
    { "name": "개발본부", "amount": 200, "memo": "개발본부 memo Line", "depth": 1 }
];



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - DrillDown 트리(inputType="drilldown" + depthColumn) + MultiLine(레코드당 2 Line) 그리드 1개 동적 생성.
//    · header / gBody 각각 <w2:row> 2개 → 레코드당 2 Line.
//      Line1 : name(drilldown) / amount
//      Line2 : memo(일반 text, colspan 병합)
//    · showDepth="1" → 초기엔 depth1(부모)만 표시, 자식은 접힘. getDescendantRowIndexArray 는
//      DataList 인덱스 기반이라 접힘/펼침과 무관하게 동작.
scwin.comp_init = async function () {
    // 기존 target / dataList 정리
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] DrillDown 트리 + MultiLine(레코드당 2 Line: Line1=이름(drilldown)/금액, Line2=메모). 데이터(DataList idx): 영업본부(0) > 영업1팀(1) > 김영업(2), 개발본부(3). 한 레코드가 화면상 2개 TR 로 보여도 rowIndex 는 DataList 인덱스 하나뿐.\n[절차] par_rowIndex(DataList 인덱스) 선택 후 getDescendantRowIndexArray 버튼 클릭.\n[확인] MultiLine 이어도 rowIndex 는 각 Line 이 동일하므로, 영업본부(0)의 모든 자손이 하나의 배열 [1,2](영업1팀+손자 김영업)로 반환됨."', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="depth" name="depth" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON(scwin.GRID_DATA, false);

    // DrillDown + MultiLine : header / gBody 각각 <w2:row> 2개 (레코드당 2 Line)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" rowNumVisible="true" defaultCellHeight="30" id="" style="width:560px;height:360px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getDescendantRowIndexArray (DrillDown + MultiLine) 테스트 그리드"></w2:caption>';
    // Header : Line1(이름/금액) / Line2(메모)
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="360" style="" inputType="text" id="hcol_name" value="이름(drilldown)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol_amount" value="금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="*" colspan="2" style="" inputType="text" id="hcol_memo" value="메모(2번째 Line)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    // gBody : Line1(name drilldown, amount) / Line2(memo 일반 text) → 레코드당 2 TR Line
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="360" style="" inputType="drilldown" depthColumn="depth" showDepth="1" depthStartIndex="1" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="amount" dataList="amount"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    strTarget += '<w2:column width="*" colspan="2" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// [getDescendantRowIndexArray] MultiLine caveat 검증 :
//  - MultiLine 이라 한 레코드가 화면상 Line1/Line2 두 TR 로 렌더되지만 rowIndex(DataList 인덱스)는 하나뿐.
//    그 rowIndex 로 getDescendantRowIndexArray 를 호출하면 두 Line 공통의 모든 자손 배열이 반환됨.
scwin.btn_getDescendantRowIndexArray_onclick = function () {
    let b = wf_body_bottom.getObj("scwin");
    let rowIndex = parseInt(par_rowIndex.getValue(), 10);

    let result = target1.getDescendantRowIndexArray(rowIndex);
    b.setReturnValue("getDescendantRowIndexArray(" + rowIndex + ") 반환 : " + JSON.stringify(result));

    // DataList 기준 자손 매핑 (Leaf 이면 빈 배열)
    let baseName = dlt_bind.getCellData(rowIndex, "name");
    let childText;
    if (!result || result.length === 0) {
        childText = "(자식 없음 - 빈 배열)";
    } else {
        childText = result.map(function (idx) { return "idx" + idx + "(" + dlt_bind.getCellData(idx, "name") + ")"; }).join(", ");
    }
    b.setReturnValue("조회 Row : idx" + rowIndex + "(" + baseName + ") -> 모든 자식(자손) : " + childText);
};
